  function openModal(type:string){setFormName('');setFormQuestion('');if(type==='scenario')setFormFeature(userFeatures.some(f=>f.feature_id===scenario?.feature_id)?scenario!.feature_id:userFeatures[0]?.feature_id||'');setModal(type);}
  async function openLocalProject(analyze:boolean){
    const switchVersion=projectSwitch.current;
    const p=await api.invoke<Project>('open_project_path',{path:formName.trim()});
    let target='';
    try{
      const workspace=await reload();
      // Reopening a project resumes its saved work; it never silently pays for another analysis.
      const hasReading=workspace.explanations.some(e=>e.result.binding.project_id===p.project_id)||workspace.runs.some(r=>r.binding.project_id===p.project_id&&!r.reading_question_id);
      if(analyze&&!hasReading){
        target=(await api.invoke<Scenario>('overview_create',{project_id:p.project_id})).scenario_id;
        await api.invoke('reading_save',{key:'feature-expand-mode/'+p.project_id,value:{mode:'codex',version:1}});
        await api.invoke('run_start',{scenario_id:target,provider_id:'codex',submission_key:crypto.randomUUID()});
      }
    }finally{
      const workspace=await reload();
      if(projectSwitch.current===switchVersion){
        await chooseProject(workspace.projects.find(item=>item.project_id===p.project_id)!,workspace);
        if(target&&projectSwitch.current===switchVersion+1){
          navigation.current={scope:p.project_id+'/'+target,value:{entrance:'overview',view:'system',detail_tab:'agent',mode:'normal'}};
          setScenarioId(target);setExpandMode('codex');
        }
      }
      setModal('');
    }
  }
  async function submitForm(e:React.FormEvent,analyze=true){e.preventDefault();if(pending)return;setPending(true);
    try{await action(async()=>{
      if(modal==='feature'){const r=await api.invoke('feature_add',{project_id:projectId,name:formName,question:formQuestion});await reload();setScenarioId(r.scenario.scenario_id);}
      if(modal==='scenario'){const r=await api.invoke('scenario_add',{feature_id:formFeature,question:formQuestion});await reload();setScenarioId(r.scenario_id);}
      if(modal==='revise')await api.invoke('scenario_revise',{scenario_id:scenarioId,question:formQuestion});
      if(modal==='featureRename')await api.invoke('organize',{kind:'feature',id:renameFeature,patch:{name:formName}});
      if(modal==='rename')await api.invoke('organize',{kind:'scenario',id:scenarioId,patch:{title:formName}});
      if(modal==='open')await openLocalProject(analyze);
      if(modal==='build')await api.invoke('refresh',{project_id:projectId,build_config:formQuestion});
      setModal('');setNotice('已保存');await reload();
    });}finally{setPending(false);}
  }
  function setAnalysisMode(mode:string){setExpandMode(mode);void action(()=>api.invoke('reading_save',{key:'feature-expand-mode/'+projectId,value:{mode,version:1}}));}
  function chooseAnalysisProvider(providerId:string){if(!['codex','dsh','workbuddy'].includes(providerId))return;setProvider(providerId);void action(()=>api.invoke('reading_save',{key:'analysis-provider/'+projectId,value:{provider_id:providerId}}));}
  async function requestAnalysis(overview=false){
    if(starting.current||pending||running||!project)return;starting.current=true;setPending(true);
    try{await action(async()=>{let target=scenarioId;if(overview)target=(await api.invoke<Scenario>('overview_create',{project_id:projectId})).scenario_id;
      if(expandMode==='mcp')await api.invoke('analysis_prepare',{scenario_id:target});
      else await api.invoke('run_start',{scenario_id:target,provider_id:'codex',submission_key:crypto.randomUUID()});
      await reload();chooseScenario(target,{entrance:overview?'overview':'walk',view:overview?'system':'timeline',detail_tab:'agent',mode:'normal'});
    });}finally{starting.current=false;setPending(false);}
  }
  async function researchOverview(){
    if(starting.current||pending||projectTasks.length||!result||!overviewReviewGaps.length||project?.fictional||indexes[projectId])return;
    const resultId=result.result_id,key=activeReadingKey.current,switchVersion=projectSwitch.current;
    starting.current=true;setPending(true);
    // Pin this version before the asynchronous run so a newly saved result
    // cannot replace the graph or source the user is currently reading.
    patch({result_id:resultId});showRun();
    try{await action(async()=>{
      await api.invoke<Run>('overview_research',{result_id:resultId,submission_key:crypto.randomUUID()});
      await reload();
      if(activeReadingKey.current===key&&projectSwitch.current===switchVersion)setNotice('已在 ARC 内启动关系补查；当前说明和阅读位置保留。');
    });}finally{starting.current=false;setPending(false);}
  }
  function openTask(sceneId:string){const s=data.scenarios.find(s=>s.scenario_id===sceneId);if(!s)return;chooseScenario(sceneId,{entrance:sceneId===project?.overview_scenario_id?'overview':'walk',view:sceneId===project?.overview_scenario_id?'system':'timeline',mode:'normal',detail_tab:'agent',result_id:''});}
  function viewCompleted(){if(!completedExplanation)return;patch({scroll:{...reading.scroll,[`canvas-${reading.view}`]:{top:0,left:0},[`detail-${reading.view}-details`]:{top:0,left:0}},result_id:completedExplanation.result_id,reading_path:'',function_path:'',reading_focus:'',selected:'',file:'',evidence_id:'',source_snapshot_id:completedExplanation.result.binding.source_snapshot_id,detail_tab:'details',mode:'normal'});if(width<900)setShowDetail(false);}
  function viewFeatureResult(resultId:string){const next=sceneExplanations.find(item=>item.result_id===resultId);if(!next)return;patch({result_id:next.result_id,reading_path:'',function_path:'',reading_focus:'',selected:'',file:'',evidence_id:'',source_snapshot_id:next.result.binding.source_snapshot_id,detail_tab:'details',mode:'normal'});if(width<900)setShowDetail(false);}
  function openFeatureTask(taskId:string){void action(async()=>{await api.invoke('reading_save',{key:'engineering-selection/'+projectId,value:{task_id:taskId,project_id:projectId,section:'tasks'}});switchView('engineering',{mode:'normal',catalog_hidden:true});});}
  function showMcp(){closePopovers();setPaths(v=>({...v,codex_path:v.codex_path||data.providers.find(p=>p.provider_id==='codex')?.path||''}));setModal('settings');void api.invoke('settings').then(setSettings);void api.invoke('mcp_status').then(setMcp);}
  function askHere(){patch({detail_tab:'questions'});setShowDetail(true);requestAnimationFrame(()=>document.getElementById('reading-question-input')?.focus());}
  function showRun(){setReading(r=>({...r,detail_tab:'agent',scroll:{...r.scroll,[`detail-${r.view}-agent`]:{top:0,left:0}}}));setActivityFocus(n=>n+1);setShowDetail(featureReading||width<900);}
  const analysisLabel=pending?'正在提交…':running?`${statuses[running.status]} · 查看任务`:waitingMcp?(expandMode==='mcp'?'查看待领取任务':'改用 Codex 直接分析'):catalogReading?(catalogExplanation?'更新工程全貌与目录':'发现工程功能'):reading.entrance==='overview'?(result?'重新分析工程':'开始工程分析'):scenario?.kind==='feature_overview'?(result?'重新分析功能':'开始功能分析'):scenario?(result?'重新分析场景':'开始场景分析'):'添加功能';
  const beginAnalysis=()=>running||(waitingMcp&&expandMode==='mcp')?showRun():catalogReading?void requestAnalysis(true):reading.entrance==='walk'&&!scenario?openModal('feature'):void requestAnalysis(reading.entrance==='overview');
  const analysisButton=<button className="primary analysis-start" disabled={pending||project?.fictional||!!indexes[projectId]} onClick={beginAnalysis}>{analysisLabel}</button>;
  function setEntrance(entrance:'overview'|'walk'){emptyEntrance.current=entrance;chooseScenario(entrance==='overview'?project?.overview_scenario_id||'':'',{entrance,view:entrance==='walk'?'capabilities':'system',mode:'normal',catalog_hidden:false});}
  function openWorkbench(view:'overview'|'walk'|'functions'|'engineering'){
    if(!project){openModal('open');return;}
    if(view==='overview'||view==='walk'){setEntrance(view);return;}
    if(view==='engineering'){switchView('engineering',{mode:'normal',catalog_hidden:true});return;}
    if(result?.nodes.some(n=>n.kind==='function')){switchView('functions',{mode:'normal',catalog_hidden:true});return;}
    const available=[...data.explanations].reverse().find(e=>e.result.binding.project_id===projectId&&e.result.nodes.some(n=>n.kind==='function')&&walkScenes.some(s=>s.scenario_id===e.scenario_id));
    if(available){const path=available.result.function_walkthroughs?.[0];chooseScenario(available.scenario_id,{entrance:'walk',view:'functions',mode:'normal',catalog_hidden:true,result_id:available.result_id,source_snapshot_id:available.result.binding.source_snapshot_id,function_path:path?.id||'',selected:path?.entry_node_id||'',detail_tab:'details'});return;}
    setEntrance('walk');setNotice('先选择或添加一个功能，在 ARC 内分析后即可从真实入口查看调用链。');
  }
  async function openCapability(nodeId:string){
    if(starting.current||!catalogExplanation)return;starting.current=true;setPending(true);
    try{await action(async()=>{
      const opened=await api.invoke('feature_open',{project_id:projectId,result_id:catalogExplanation.result_id,node_id:nodeId,request_mcp:expandMode==='mcp'});
      if(expandMode==='codex'&&!opened.result_id&&!opened.run_id)await api.invoke('run_start',{scenario_id:opened.scenario.scenario_id,provider_id:'codex',submission_key:crypto.randomUUID()});
      await reload();emptyEntrance.current='walk';chooseScenario(opened.scenario.scenario_id,{entrance:'walk',view:'timeline',mode:'normal',result_id:opened.result_id||'',selected:'',detail_tab:opened.result_id?'details':'agent'});
      if(opened.run_id){showRun();return;}
      if(opened.result_id)return;
      return;
    });}finally{starting.current=false;setPending(false);}
  }
  const changeWidth=(side:'left_width'|'right_width',amount:number)=>patch({[side]:Math.min(side==='left_width'?300:Math.max(280,width-(reading.mode==='source'?820:reading.left_width+480)),Math.max(side==='left_width'?200:280,reading[side]+amount))});
  const featureOpen=(id:string)=>reading.expanded.includes('feature-open/'+id)||(!reading.expanded.includes('feature-closed/'+id)&&scenario?.feature_id===id);
  function toggleFeature(id:string){const open=featureOpen(id);patch({expanded:[...reading.expanded.filter(v=>v!=='feature-open/'+id&&v!=='feature-closed/'+id),(open?'feature-closed/':'feature-open/')+id]});}
  const primaryViews=reading.entrance==='overview'?[['system','系统协作'],['capabilities','功能总览'],['functions','调用链'],['modules','内部模块'],['files','文件组织'],['dependencies','依赖关系']]:featureViews;
